"""Execution context for runtime trace expansion."""

from __future__ import annotations

from dataclasses import dataclass, field

from qamc.ir.model import ExecutionSpec, SystemModel, TraceSpec
from qamc.runtime.anchor_store import AnchorStore
from qamc.runtime.state_node import StateNode
from qamc.runtime.transition_edge import TransitionEdge


@dataclass(slots=True)
class ExecutionContext:
    """All runtime objects generated by one execution."""

    system_model: SystemModel
    trace: TraceSpec
    execution: ExecutionSpec
    nodes: dict[str, StateNode] = field(default_factory=dict)
    edges: list[TransitionEdge] = field(default_factory=list)
    anchors: AnchorStore = field(default_factory=lambda: AnchorStore(anchor_kind={}))
    node_counter: int = 0

    def new_node_id(self) -> str:
        self.node_counter += 1
        return f"n{self.node_counter}"

    def add_node(self, node: StateNode) -> None:
        self.nodes[node.id] = node

    def add_edge(self, edge: TransitionEdge) -> None:
        self.edges.append(edge)

    def node(self, node_id: str) -> StateNode:
        return self.nodes[node_id]
